    public sealed class TypedSubscriptionBuilder
    {
        private readonly IDbConnection conn;
        private Action<SubscriptionEventContext>? Applied;
        private Action<ErrorContext, Exception>? Error;
        private readonly List<string> querySqls = new();

        internal TypedSubscriptionBuilder(IDbConnection conn, Action<SubscriptionEventContext>? applied, Action<ErrorContext, Exception>? error)
        {
            this.conn = conn;
            Applied = applied;
            Error = error;
        }

        public TypedSubscriptionBuilder OnApplied(Action<SubscriptionEventContext> callback)
        {
            Applied += callback;
            return this;
        }

        public TypedSubscriptionBuilder OnError(Action<ErrorContext, Exception> callback)
        {
            Error += callback;
            return this;
        }

        public TypedSubscriptionBuilder AddQuery<TRow>(Func<QueryBuilder, global::SpacetimeDB.IQuery<TRow>> build)
        {
            var qb = new QueryBuilder();
            querySqls.Add(build(qb).ToSql());
            return this;
        }

        public SubscriptionHandle Subscribe() => new(conn, Applied, Error, querySqls.ToArray());
    }

    public abstract partial class Reducer
    {
        private Reducer() { }
    }

    public abstract partial class Procedure
    {
        private Procedure() { }
    }

    public sealed class DbConnection : DbConnectionBase<DbConnection, RemoteTables, Reducer>
    {
        public override RemoteTables Db { get; }
        public readonly RemoteReducers Reducers;
        public readonly RemoteProcedures Procedures;

        public DbConnection()
        {
            Db = new(this);
            Reducers = new(this);
            Procedures = new(this);
        }

        protected override IEventContext ToEventContext(Event<Reducer> Event) =>
        new EventContext(this, Event);

        protected override IReducerEventContext ToReducerEventContext(ReducerEvent<Reducer> reducerEvent) =>
        new ReducerEventContext(this, reducerEvent);

        protected override ISubscriptionEventContext MakeSubscriptionEventContext() =>
        new SubscriptionEventContext(this);

        protected override IErrorContext ToErrorContext(Exception exception) =>
        new ErrorContext(this, exception);

        protected override IProcedureEventContext ToProcedureEventContext(ProcedureEvent procedureEvent) =>
        new ProcedureEventContext(this, procedureEvent);

        protected override bool Dispatch(IReducerEventContext context, Reducer reducer)
        {
            var eventContext = (ReducerEventContext)context;
            return reducer switch
            {
                Reducer.CancelQuickMatch args => Reducers.InvokeCancelQuickMatch(eventContext, args),
                Reducer.CancelRankedMatch args => Reducers.InvokeCancelRankedMatch(eventContext, args),
                Reducer.CancelTournament args => Reducers.InvokeCancelTournament(eventContext, args),
                Reducer.ChooseInitialSkill args => Reducers.InvokeChooseInitialSkill(eventContext, args),
                Reducer.CloseSeason args => Reducers.InvokeCloseSeason(eventContext, args),
                Reducer.ConfirmPreparation args => Reducers.InvokeConfirmPreparation(eventContext, args),
                Reducer.CreateRoom args => Reducers.InvokeCreateRoom(eventContext, args),
                Reducer.DeleteAccount args => Reducers.InvokeDeleteAccount(eventContext, args),
                Reducer.DeleteAccountOf args => Reducers.InvokeDeleteAccountOf(eventContext, args),
                Reducer.DeleteDeck args => Reducers.InvokeDeleteDeck(eventContext, args),
                Reducer.EnsureDuel args => Reducers.InvokeEnsureDuel(eventContext, args),
                Reducer.FindQuickMatch args => Reducers.InvokeFindQuickMatch(eventContext, args),
                Reducer.FindRankedMatch args => Reducers.InvokeFindRankedMatch(eventContext, args),
                Reducer.JoinRoom args => Reducers.InvokeJoinRoom(eventContext, args),
                Reducer.JoinTournament args => Reducers.InvokeJoinTournament(eventContext, args),
                Reducer.KeepQuickMatchAlive args => Reducers.InvokeKeepQuickMatchAlive(eventContext, args),
                Reducer.KeepRankedMatchAlive args => Reducers.InvokeKeepRankedMatchAlive(eventContext, args),
                Reducer.LeaveRoom args => Reducers.InvokeLeaveRoom(eventContext, args),
                Reducer.OpenSeason args => Reducers.InvokeOpenSeason(eventContext, args),
                Reducer.OpenTournament args => Reducers.InvokeOpenTournament(eventContext, args),
                Reducer.PlayDuelV2 args => Reducers.InvokePlayDuelV2(eventContext, args),
                Reducer.SaveDeckV2 args => Reducers.InvokeSaveDeckV2(eventContext, args),
                Reducer.SetActiveDeck args => Reducers.InvokeSetActiveDeck(eventContext, args),
                Reducer.SetComboResponses args => Reducers.InvokeSetComboResponses(eventContext, args),
                Reducer.SetDeckCover args => Reducers.InvokeSetDeckCover(eventContext, args),
                Reducer.SetDisplayName args => Reducers.InvokeSetDisplayName(eventContext, args),
                Reducer.SetHomeStyle args => Reducers.InvokeSetHomeStyle(eventContext, args),
                Reducer.SetProfile args => Reducers.InvokeSetProfile(eventContext, args),
                Reducer.SetTournamentReady args => Reducers.InvokeSetTournamentReady(eventContext, args),
                Reducer.StartTournament args => Reducers.InvokeStartTournament(eventContext, args),
                Reducer.WithdrawFromTournament args => Reducers.InvokeWithdrawFromTournament(eventContext, args),
                _ => throw new ArgumentOutOfRangeException("Reducer", $"Unknown reducer {reducer}")
            };
        }

        public SubscriptionBuilder SubscriptionBuilder() => new(this);
        public event Action<ReducerEventContext, Exception> OnUnhandledReducerError
        {
            add => Reducers.InternalOnUnhandledReducerError += value;
            remove => Reducers.InternalOnUnhandledReducerError -= value;
        }
    }
}
